-- IP-005 Large transfer to the customer's own account at another bank, linked days ago
SELECT 'IP-005' AS rule_id, 'transactions' AS anchor_table, a.id AS anchor_id
FROM transactions AS a
WHERE (a.direction = 'out' AND a.channel IN ('rtp', 'fednow', 'p2p', 'wire') AND a.payee_self = 1 AND a.amount_cents >= 200000 AND a.ts < (a.counterparty_linked_ts + 259200));
